PRAGMA foreign_keys = ON;

CREATE TABLE accounts (id TEXT PRIMARY KEY NOT NULL, github_user_id TEXT NOT NULL UNIQUE, display_name TEXT, deleted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT);
CREATE TABLE credentials (id TEXT PRIMARY KEY NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT, revoked_at TEXT, created_at TEXT NOT NULL, updated_at TEXT);
CREATE TABLE seasons (id TEXT PRIMARY KEY NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','generated','validated','published','active','ended','revealed')), ruleset_version TEXT NOT NULL, generator_version TEXT NOT NULL, content_version TEXT NOT NULL, seed_commitment TEXT, revealed_seed TEXT, retention_state TEXT NOT NULL DEFAULT 'active' CHECK(retention_state IN ('active','historical','compacted')), created_at TEXT NOT NULL, updated_at TEXT);
CREATE TABLE characters (id TEXT PRIMARY KEY NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id), season_id TEXT NOT NULL REFERENCES seasons(id), sequence INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('living','dead','retired')), state_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT, UNIQUE(account_id, season_id, sequence));
CREATE TABLE runs (id TEXT PRIMARY KEY NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id), season_id TEXT NOT NULL REFERENCES seasons(id), character_id TEXT REFERENCES characters(id), mode TEXT NOT NULL CHECK(mode IN ('ranked','practice')), status TEXT NOT NULL, state_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT);
CREATE TABLE floor_sessions (id TEXT PRIMARY KEY NOT NULL, run_id TEXT NOT NULL REFERENCES runs(id), floor INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','paused','completed','abandoned','expired')), definition_json TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT);
CREATE INDEX floor_sessions_active_run ON floor_sessions(run_id, status);
CREATE TABLE snapshots (floor_session_id TEXT PRIMARY KEY NOT NULL REFERENCES floor_sessions(id), version INTEGER NOT NULL, checksum TEXT NOT NULL, snapshot_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE events (id TEXT PRIMARY KEY NOT NULL, floor_session_id TEXT NOT NULL REFERENCES floor_sessions(id), sequence INTEGER NOT NULL, event_json TEXT NOT NULL, checksum TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(floor_session_id, sequence));
CREATE TABLE mutation_receipts (scope_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(scope_id, idempotency_key));
CREATE TABLE journals (id TEXT PRIMARY KEY NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id), season_id TEXT REFERENCES seasons(id), kind TEXT NOT NULL CHECK(kind IN ('fact','note')), payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE charges (account_id TEXT PRIMARY KEY NOT NULL REFERENCES accounts(id), available INTEGER NOT NULL CHECK(available BETWEEN 0 AND 3), calculated_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE standings (season_id TEXT NOT NULL REFERENCES seasons(id), account_id TEXT NOT NULL REFERENCES accounts(id), best_floor INTEGER NOT NULL, bosses_defeated INTEGER NOT NULL, character_deaths INTEGER NOT NULL, floor_turns INTEGER NOT NULL, achieved_at TEXT NOT NULL, PRIMARY KEY(season_id, account_id));
